using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class ProvinceConfiguration:IEntityTypeConfiguration<Province>{ public void Configure(EntityTypeBuilder<Province>b){ b.HasKey(x=>x.ProvinceID); b.Property(x=>x.ProvinceName).HasMaxLength(100).IsRequired(); b.Property(x=>x.Slug).HasMaxLength(250); b.Property(x=>x.SeoTitle).HasMaxLength(200); b.Property(x=>x.SeoDescription).HasMaxLength(500); b.Property(x=>x.SeoKeywords).HasMaxLength(500); b.Property(x=>x.CanonicalUrl).HasMaxLength(500); b.Property(x=>x.OpenGraphImageUrl).HasMaxLength(500); b.HasIndex(x=>x.ProvinceName).IsUnique(); b.HasIndex(x=>x.Slug).IsUnique().HasFilter("[Slug] IS NOT NULL"); }}